from sympy import symbols, solve, Poly, sqrt, N

# Define the polynomial Q(u) = u^4 - 3u^3 + 9
u = symbols('u')
Q = Poly(u**4 - 3*u**3 + 9, u)

# Find all roots
roots = solve(u**4 - 3*u**3 + 9, u)

print("The roots of u^4 - 3u^3 + 9 = 0 are:")
for root in roots:
    # Convert symbolic roots to numerical approximations for checking
    try:
        num_root = N(root)
        print(f"  {num_root}")
    except Exception:
        # Handle cases where numerical evaluation might fail for complex numbers or very high precision
        print(f"  {root}")

# Check for non-negative real roots
def is_real_and_non_negative(root):
    # SymPy roots can be complex numbers. Check if the imaginary part is zero (within tolerance)
    if root.is_real:
        return root >= 0
    return False

print("\nChecking if any roots are non-negative real numbers:")
non_negative_real_roots = []
for root in roots:
    if is_real_and_non_negative(root):
        non_negative_real_roots.append(root)

if non_negative_real_roots:
    print("Found non-negative real roots:")
    for r in non_negative_real_roots:
        print(r)
else:
    print("No non-negative real roots found.")
